/* @autogenerated */
import { booleanAttribute, ChangeDetectionStrategy, Component, inject, input } from '@angular/core';
import { RuntimeThemeService } from '@shared/context/theme/runtime-theme.service';

let nextId = 0;

/**
 * Cabecera de las páginas del shell (entrada, página desconocida…): la marca del producto o una ilustración, un
 * título, un texto y las acciones que proyecte la página. Lo que vaya con el atributo `hint` sale debajo de ellas.
 */
@Component({
  selector: 'app-hero-section',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './hero-section.component.html',
  styleUrl: './hero-section.component.scss',
})
export class HeroSectionComponent {
  private readonly theme = inject(RuntimeThemeService);

  /** Ya traducido. */
  readonly title = input.required<string>();
  readonly lead = input<string>();
  /** Muestra el logo y el nombre del producto encima del título. */
  readonly brand = input(false, { transform: booleanAttribute });
  /** Ilustración decorativa encima del título (ruta del recurso). */
  readonly image = input<string>();

  readonly logo = this.theme.logo;
  readonly productName = this.theme.productName;
  readonly titleId = `hero-title-${nextId++}`;
}
